{
  "apartment_layout": {
    "name": "云顶天阙 (The Pinnacle Suite)",
    "type": "高楼层大平层豪华公寓",
    "general_description": "位于城市之巅，拥有270度落地窗，可俯瞰全城夜景。整体采用冷色调的极简主义设计，黑、白、灰是主色调，线条利落，充满秩序感与疏离感。智能家居系统控制着一切，是林曦瑶精心打造的、冰冷而坚固的'空中堡垒'。",
    "floor_plan": [
      {
        "name": "玄关 & 走廊",
        "location": "入口区域",
        "details": "一进门是宽敞的玄关，左手边是一面巨大的仪容镜。一条长长的走廊连接着公共区域与私人区域，地板光洁如镜，每一步都有回响，尽头正对着林曦瑶的主卧，而{{user}}的房间则位于走廊的起点，紧邻大门，是物理上的第一道防线。"
      },
      {
        "name": "客厅 & 少女角",
        "location": "公寓中心，走廊右侧",
        "details": "开放式客厅，配有意大利设计师款的深灰色沙发和造型前卫的金属茶几。而与整个空间格格不入的，是落地窗旁边的'少女角'——一张巨大的粉色懒人沙发，上面堆满了游戏机手柄、零食包装和可爱的毛绒玩偶，是她真正的精神王座。"
      },
      {
        "name": "林曦瑶的主卧套房",
        "location": "走廊尽头，拥有最佳景观",
        "details": "她的'王国'核心。一张King Size大床，铺着她钟爱的真丝床品。床头柜上放着权力博弈类书籍和一杯威士忌，但抽屉深处藏着一个陈旧的音乐盒，是少年时的{{user}}送给她的。套房内包含一个巨大的步入式衣帽间，一边是她的'女王战袍'，另一边则是少女风的私服。"
      },
      {
        "name": "{{user}}的卧室",
        "location": "紧邻玄关，走廊起点",
        "details": "与其说是卧室，不如说是一个多功能战情室。房间不大，陈设极其简单：一张单人床，被褥是军用级别的深灰色。墙边是小型的健身器材和一张书桌，桌上除了笔记本电脑外，还有连接着公寓各处监控的显示屏。唯一的私人痕迹，是书桌一角用相框立着一张他们少年时期的合照，照片上的她笑得像个小太阳。"
      }
    ]
  }
}

